// --------------------------------------------------------------------------- //
// Trie
// --------------------------------------------------------------------------- //

describe("trie", () => {
  const trie = new Trie(
    Object.fromEntries(trieGolden.words.map((w) => [w, `https://example.com/${w}`])),
  );

  it("matches the Python on every prefix query", () => {
    for (const [query, expected] of Object.entries(trieGolden.prefix)) {
      expect([...trie.keysWithPrefix(query)].sort()).toEqual(expected);
    }
  });

  it("matches the Python on every wildcard query", () => {
    for (const [query, expected] of Object.entries(trieGolden.wildcard)) {
      const got = [...trie.wildcardSearch(query)].map(([k]) => k).sort();
      expect(got).toEqual(expected);
    }
  });

  it("holds every word", () => {
    expect(trie.size).toBe(trieGolden.words.length);
    expect([...trie.keys()].sort()).toEqual([...trieGolden.words].sort());
  });

  it("folds letters case-insensitively and everything else into one bucket", () => {
    expect(characterToKey("a")).toBe(0);
    expect(characterToKey("A")).toBe(0);
    expect(characterToKey("z")).toBe(25);
    for (const c of ["1", " ", "-", "'"]) expect(characterToKey(c)).toBe(26);
  });

  it("rejects a multi-character input", () => {
    expect(() => characterToKey("ab")).toThrow();
  });

  it("does not treat a prefix of a key as a key", () => {
    expect(trie.has("par")).toBe(false);
    expect(trie.has("park")).toBe(true);
  });

  it("reports the walked path for the visualisation", () => {
    expect(trie.pathFor("par")).toHaveLength(4); // root + p + a + r
    expect(trie.pathFor("zzz")).toHaveLength(1); // root only
  });
});

// --------------------------------------------------------------------------- //
// Card scoring
// --------------------------------------------------------------------------- //

describe("card scoring", () => {
  it("matches the Python on all 400 golden hands", () => {
    let checked = 0;
    for (const testCase of cardsGolden.cases) {
      const hand = testCase.hand.map((c) => ({
        suit: c.suit as Suit,
        rank: c.rank as Rank,
      }));
      expect(scoreCards(hand)).toBe(testCase.rank);
      checked += 1;
    }
    expect(checked).toBe(400);
  });

  it("agrees with the Python point table", () => {
    for (const testCase of cardsGolden.cases.slice(0, 50)) {
      expect(HAND_SCORES[scoreCards(
        testCase.hand.map((c) => ({ suit: c.suit as Suit, rank: c.rank as Rank })),
      )]).toBe(testCase.points);
    }
  });

  const hand = (...specs: string[]): Card[] => {
    const suits: Record<string, Suit> = {
      C: "clubs", D: "diamonds", H: "hearts", S: "spades",
    };
    return specs.map((s) => ({
      suit: suits[s.slice(-1)],
      rank: s.slice(0, -1) as Rank,
    }));
  };

  it("scores a six-card flush, which the original missed", () => {
    expect(scoreCards(hand("2H", "4H", "6H", "8H", "10H", "QH", "3S"))).toBe("Flush");
  });

  it("scores two triples as a full house, which the original missed", () => {
    expect(scoreCards(hand("2H", "2S", "2C", "5H", "5S", "5C", "9D"))).toBe("FullHouse");
  });

  it("scores an empty hand as nothing", () => {
    expect(scoreCards([])).toBe("None");
  });
});

